if($filters['questionnaire_id']<=0&&$questionnaires)$filters['questionnaire_id']=(int)$questionnaires[0]['id']; $selectedLocation=max(0,(int)($_GET['location_id']??0));
$departments=department_options($pdo); $workFunctions=work_function_choices($pdo); $teamOptions=[]; $catalog=department_team_catalog($pdo);
foreach($catalog as $v){if(is_array($v)&&isset($v['slug'])){$teamOptions[(string)$v['slug']]=(string)($v['label']??$v['slug']);}elseif(is_array($v)){foreach($v as $team){if(is_array($team)&&!empty($team['slug']))$teamOptions[(string)$team['slug']]=(string)($team['label']??$team['slug']);}}}
$locations=location_records($pdo,false); $locationById=location_map_by_id($pdo,false);
$scope=analytics_capacity_latest_per_employee(analytics_capacity_fetch_response_rows($pdo,$filters,true,true)); $userLoc=[];$ids=array_values(array_unique(array_filter(array_map(fn($r)=>(int)($r['user_id']??0),$scope))));
if($ids){$s=$pdo->prepare('SELECT id,location_id FROM users WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$s->execute($ids);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r)$userLoc[(int)$r['id']]=(int)($r['location_id']??0);}
$rows=[];$unassigned=0;foreach($scope as $r){$lid=$userLoc[(int)$r['user_id']]??0;if(!$lid)$unassigned++;if($selectedLocation&&$lid!==$selectedLocation)continue;$r['location_id']=$lid;$rows[]=$r;}
$assigned=[];$sql="SELECT location_id,COUNT(*) c FROM users WHERE role='staff' AND account_status='active'";$params=[];
foreach([['department','department'],['team','cadre'],['work_function','work_function']] as [$fk,$col]){if($filters[$fk]!==''){$sql.=" AND $col=?";$params[]=$filters[$fk];}} if($selectedLocation){$sql.=' AND location_id=?';$params[]=$selectedLocation;} $sql.=' GROUP BY location_id';
$s=$pdo->prepare($sql);$s->execute($params);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r)$assigned[(int)($r['location_id']??0)]=(int)$r['c'];
$group=[];foreach($rows as $r){$lid=(int)$r['location_id'];if($lid)$group[$lid][]=$r;}
