<style nonce="<?=htmlspecialchars(csp_nonce(),ENT_QUOTES,'UTF-8')?>">:root{--b:#1565c0}.gis-page{max-width:1500px;margin:auto;padding:1rem}.gis-head{display:flex;justify-content:space-between;gap:1rem}.gis-head h1{margin:0;color:#10233f}.analytics-tabs{display:flex;gap:.25rem;border-bottom:1px solid #d9e1ec;margin:1rem 0;overflow:auto}.analytics-tabs a{padding:.7rem .9rem;text-decoration:none;color:#2d3748;border-bottom:3px solid transparent;white-space:nowrap;font-weight:600}.analytics-tabs a.is-active{color:var(--b);border-bottom-color:var(--b)}.filters{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr)) auto;gap:.6rem;align-items:end}.filters label{display:flex;flex-direction:column;gap:.25rem;font-size:.8rem;font-weight:600}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:.8rem;margin:1rem 0}.kpi,.card{background:#fff;border:1px solid #dfe6ef;border-radius:12px;padding:1rem;box-shadow:0 2px 8px rgba(15,35,60,.06)}.kpi small{display:block;color:#687386;text-transform:uppercase}.kpi strong{font-size:1.7rem;color:#14345c}.grid{display:grid;grid-template-columns:8fr 4fr;gap:1rem}.map{height:560px;border:1px solid #dce4ed;border-radius:10px}.card h2{margin:0 0 .5rem;color:#0d47a1;font-size:1.05rem}.full{grid-column:1/-1}.note{border-left:4px solid #ef6c00;background:#fff8ed;padding:.7rem;margin:.7rem 0;font-size:.82rem}.table-wrap{overflow:auto}.tbl{width:100%;border-collapse:collapse;font-size:.83rem}.tbl th,.tbl td{padding:.52rem;border-bottom:1px solid #e7edf4;text-align:left}.tbl th{background:#f8fafc}.pill{display:inline-block;min-width:58px;text-align:center;padding:.2rem .4rem;border-radius:6px;font-weight:700}.good{background:#e8f5e9;color:#1b5e20}.mid{background:#fff8e1;color:#8d6e00}.low{background:#fff3e0;color:#e65100}.crit{background:#ffebee;color:#b71c1c}.empty{background:#f3f4f6;color:#6b7280}@media(max-width:1100px){.filters{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.full{grid-column:auto}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.filters,.kpis{grid-template-columns:1fr}.map{height:400px}}</style></head>
