<section class="card full"><h2>Location Comparison</h2><div class="table-wrap"><table class="tbl"><thead><tr><th>Location</th><th>Region</th><th>Assigned Staff</th><th>Assessed</th><th>Average Score</th><th>≥80%</th><th>GIS Status</th><th>Status</th></tr></thead><tbody><?php foreach($metrics as $m):$a=$m['average'];$cl=$a===null?'empty':($a>=80?'good':($a>=70?'mid':($a>=60?'low':'crit')));?><tr><td><a href="?<?=htmlspecialchars(http_build_query(array_merge($query,['location_id'=>$m['id']])),ENT_QUOTES,'UTF-8')?>"><strong><?=htmlspecialchars($m['name'],ENT_QUOTES,'UTF-8')?></strong></a></td><td><?=htmlspecialchars($m['region'],ENT_QUOTES,'UTF-8')?></td><td><?=$m['assigned']?></td><td><?=$m['assessed']?></td><td><span class="pill <?=$cl?>"><?=$a!==null?number_format($a,1).'%':'—'?></span></td><td><?=$m['attainment']!==null?number_format((float)$m['attainment'],1).'%':'—'?><?php if($m['assessed']):?><br><small><?=$m['hit']?>/<?=$m['assessed']?></small><?php endif;?></td><td><?=htmlspecialchars(ucwords(str_replace('_',' ',$m['verification'])),ENT_QUOTES,'UTF-8')?></td><td><?=$m['active']?'Active':'Inactive'?></td></tr><?php endforeach;?></tbody></table></div></section></div></main>
<?php include __DIR__.'/../templates/footer.php';?><script src="<?=htmlspecialchars($leafletJs,ENT_QUOTES,'UTF-8')?>"></script><script nonce="<?=htmlspecialchars(csp_nonce(),ENT_QUOTES,'UTF-8')?>">(function(){const pts=<?=json_encode($points,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,n=document.getElementById('gisMap');if(!n||typeof L!=='object')return;const m=L.map(n,{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(m);const b=[];pts.forEach(p=>{const c=p.verification==='verified_exact'?'#2e7d32':(p.verification==='estimated'?'#ef6c00':'#1565c0'),r=Math.max(7,Math.min(19,7+Math.sqrt(Number(p.assessed||0))*2)),q=L.circleMarker([p.lat,p.lon],{radius:r,weight:2,color:c,fillColor:c,fillOpacity:.62}).addTo(m),avg=p.average===null?'—':Number(p.average).toFixed(1)+'%',at=p.attainment===null?'—':Number(p.attainment).toFixed(1)+'%';q.bindPopup('<strong>'+esc(p.name)+'</strong><br>'+esc(p.region)+'<br>'+esc(p.address||'')+'<hr>Assigned staff: '+p.assigned+'<br>Staff assessed: '+p.assessed+'<br>Average score: '+avg+'<br>≥80% target: '+at+'<br>GIS: '+esc(String(p.verification).replaceAll('_',' ')));b.push([p.lat,p.lon]);});b.length?m.fitBounds(b,{padding:[28,28],maxZoom:7}):m.setView([9.1,40.5],5);function esc(v){return String(v??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}})();</script></body></html>
